pub fn find_median(a: &[i32], b: &[i32]) -> i32 {
    let n = a.len();
    assert!(n > 0, "arrays must be nonempty");
    assert_eq!(n, b.len(), "arrays must have the same length");

    if n % 2 == 1 {
        // odd length: return the middle element of `a`
        a[n / 2]
    } else {
        // even length: average floor((a[k-1] + b[0]) / 2)
        let k = n / 2;
        let sum: i64 = a[k - 1] as i64 + b[0] as i64;
        // using div_euclid to get floor division for negative sums
        (sum.div_euclid(2)) as i32
    }
}

